-- leveling routes: guides and their steps, taken once from the Guidelime guides (Olo, Shiku / Hakurai);
-- spots are world coordinates (map, x, y; z from the terrain at load)
DROP TABLE IF EXISTS `ai_playerbot_guide`;
CREATE TABLE `ai_playerbot_guide` (
  `id` int unsigned NOT NULL,
  `name` varchar(64) NOT NULL,
  `next` int unsigned NOT NULL DEFAULT 0 COMMENT 'the guide that follows, 0 none',
  `races` int unsigned NOT NULL DEFAULT 0 COMMENT 'race mask (1 << (race - 1)), 0 every race',
  `classes` int unsigned NOT NULL DEFAULT 0 COMMENT 'class mask (1 << (class - 1)), 0 every class',
  `min_level` tinyint unsigned NOT NULL DEFAULT 0,
  `max_level` tinyint unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

DROP TABLE IF EXISTS `ai_playerbot_guide_step`;
CREATE TABLE `ai_playerbot_guide_step` (
  `guide` int unsigned NOT NULL,
  `step` int unsigned NOT NULL COMMENT 'order in the guide',
  `type` varchar(12) NOT NULL COMMENT 'accept, turnin, complete, skip, xp, train, vendor, repair, hearth, sethearth, fly, flightpoint, collect, useitem, goto',
  `quest` int unsigned NOT NULL DEFAULT 0,
  `objective` tinyint unsigned NOT NULL DEFAULT 0 COMMENT 'complete: 1-4 one objective, 0 the quest',
  `item` int unsigned NOT NULL DEFAULT 0 COMMENT 'collect / useitem',
  `count` int unsigned NOT NULL DEFAULT 0,
  `xp_level` tinyint unsigned NOT NULL DEFAULT 0 COMMENT 'xp: the level to reach',
  `xp_points` int NOT NULL DEFAULT 0 COMMENT 'xp: + into that level, - before it',
  `place` varchar(64) NOT NULL DEFAULT '' COMMENT 'fly / sethearth / flightpoint: the place name',
  `map` smallint NOT NULL DEFAULT -1 COMMENT '-1 no spot',
  `x` float NOT NULL DEFAULT 0,
  `y` float NOT NULL DEFAULT 0,
  `races` int unsigned NOT NULL DEFAULT 0 COMMENT 'only for these races, 0 every race',
  `classes` int unsigned NOT NULL DEFAULT 0 COMMENT 'only for these classes, 0 every class',
  `optional` tinyint unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`guide`, `step`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

